{
  "category_edits": [
    {
      "category": "learning_objective",
      "rationale": "Equal sequence weighting may better align training with user-averaged HR@10. Retain the pointwise logistic terms and average valid positions within each sequence before averaging nonempty sequences across all four datasets.",
      "edits": [
        {
          "find": "    loss = nn.functional.softplus(-pos_scores) + nn.functional.softplus(neg_scores)\n    return (loss * mask).sum() / mask.sum().clamp(min=1.0)",
          "replace": "    loss = nn.functional.softplus(-pos_scores) + nn.functional.softplus(neg_scores)\n    valid_counts = mask.sum(dim=1)\n    sequence_loss = (loss * mask).sum(dim=1) / valid_counts.clamp(min=1.0)\n    nonempty = (valid_counts > 0).to(dtype=loss.dtype)\n    return (sequence_loss * nonempty).sum() / nonempty.sum().clamp(min=1.0)"
        }
      ]
    }
  ],
  "change_summary": "Change only logistic loss reduction to equal weighting of nonempty sequences. Architecture, sampling, training settings, checkpoints and predictor remain unchanged."
}
